import { expect, Locator, Page } from '@playwright/test';

export const EMPTY_EN = 'No accounts match these filters.';
export const EMPTY_HE = 'אין חשבונות שתואמים לסינון.';

/** Открыть /adminpanel и вкладку по имени («Plans» / «חבילות»). Для EN есть openPlansTab в plans-helpers.ts. */
export async function openPlansTabNamed(page: Page, tabName: string) {
  await page.goto('/adminpanel');
  await page.getByRole('tab', { name: tabName, exact: true })
    .or(page.getByRole('button', { name: tabName, exact: true }))
    .first()
    .click();
  await expect(page.getByRole('heading', { name: tabName, exact: true })).toBeVisible();
}

/** Поле поиска (placeholder «Search by name or email…»). Тот же локатор, что в targetRow(). */
export function searchBox(page: Page): Locator {
  return page.getByRole('searchbox').or(page.getByRole('textbox')).first();
}

/**
 * Строки аккаунтов: строка таблицы, в которой есть кнопка действия (у заголовка и пустого состояния кнопок нет).
 * // не проверено на сайте: разметка таблицы (tr или role=row) — по аналогии с targetRow().
 */
export function accountRows(page: Page): Locator {
  return page.locator('tr, [role="row"]').filter({ has: page.getByRole('button') });
}

/** Ждём, пока таблица загрузится, и возвращаем число строк аккаунтов. */
export async function loadedRowCount(page: Page): Promise<number> {
  const rows = accountRows(page);
  await expect(rows.first()).toBeVisible();
  return rows.count();
}

/**
 * Номер колонки по тексту заголовка.
 * // не проверено на сайте: заголовки — th или role=columnheader; в каждой строке столько же ячеек td/role=cell (последняя — кнопки без заголовка).
 */
export async function columnIndex(page: Page, header: string): Promise<number> {
  const headers = page.locator('th, [role="columnheader"]');
  await expect(headers.filter({ hasText: header }).first()).toBeVisible();
  const texts = (await headers.allInnerTexts()).map((t) => t.trim());
  const idx = texts.findIndex((t) => t === header);
  expect(idx, `колонка «${header}» не найдена среди: ${texts.join(' | ')}`).toBeGreaterThanOrEqual(0);
  return idx;
}

/** Тексты ячеек одной колонки во всех видимых строках аккаунтов. */
export async function columnValues(page: Page, header: string): Promise<string[]> {
  const idx = await columnIndex(page, header);
  const rows = accountRows(page);
  const n = await rows.count();
  const values: string[] = [];
  for (let i = 0; i < n; i++) {
    values.push((await rows.nth(i).locator('td, [role="cell"]').nth(idx).innerText()).trim());
  }
  return values;
}

/** Значение ячейки колонки в конкретной строке. */
export async function cellValue(page: Page, row: Locator, header: string): Promise<string> {
  const idx = await columnIndex(page, header);
  return (await row.locator('td, [role="cell"]').nth(idx).innerText()).trim();
}

/**
 * Фильтр по его текущей подписи по умолчанию («All plans» / «All sources» / «All statuses»).
 * Фильтры идут после поиска в порядке: план, источник, статус — берём по номеру среди combobox страницы.
 * // не проверено на сайте: фильтр — нативный <select> или кастомный combobox (на скрине — выпадающий список со стрелкой).
 */
export function filterControl(page: Page, order: 0 | 1 | 2): Locator {
  return page.getByRole('combobox').nth(order);
}
export const FILTER = { plans: 0, sources: 1, statuses: 2 } as const;

/** Список значений фильтра (без «All …»). Работает и для <select>, и для кастомного списка. */
export async function filterOptions(page: Page, control: Locator, allLabel: string): Promise<string[]> {
  const tag = await control.evaluate((el) => el.tagName.toLowerCase());
  let labels: string[];
  if (tag === 'select') {
    labels = await control.locator('option').allInnerTexts();
  } else {
    // не проверено на сайте: пункты кастомного списка — role=option.
    await control.click();
    const opts = page.getByRole('option');
    await expect(opts.first()).toBeVisible();
    labels = await opts.allInnerTexts();
    await page.keyboard.press('Escape');
    await expect(opts).toHaveCount(0);
  }
  return labels.map((l) => l.trim()).filter((l) => l && l !== allLabel);
}

/** Выбрать значение фильтра по подписи. */
export async function selectFilter(page: Page, control: Locator, label: string) {
  const tag = await control.evaluate((el) => el.tagName.toLowerCase());
  if (tag === 'select') {
    await control.selectOption({ label });
  } else {
    await control.click();
    await page.getByRole('option', { name: label, exact: true }).click();
  }
}

/** Ждём, пока применится фильтр: все строки в колонке равны value, либо показано пустое состояние. */
export async function expectColumnEqualsOrEmpty(page: Page, header: string, value: string, emptyText = EMPTY_EN) {
  await expect(async () => {
    if (await page.getByText(emptyText, { exact: true }).isVisible()) {
      expect(await accountRows(page).count()).toBe(0);
      return;
    }
    const values = await columnValues(page, header);
    expect(values.length).toBeGreaterThan(0);
    const mismatches = values.filter((v) => v !== value);
    expect(mismatches, `в колонке «${header}» должны быть только «${value}»`).toEqual([]);
  }).toPass({ timeout: 15_000 });
}

/** Каждая видимая строка содержит запрос (без учёта регистра и краевых пробелов) в имени или email. */
export async function expectAllRowsContain(page: Page, query: string) {
  const q = query.trim().toLowerCase();
  await expect(async () => {
    const texts = await columnValues(page, 'Account'); // имя + email
    expect(texts.length).toBeGreaterThan(0);
    const bad = texts.filter((t) => !t.toLowerCase().includes(q));
    expect(bad, `строки без «${q}»`).toEqual([]);
  }).toPass({ timeout: 15_000 });
}

